int select_downlink_port_checked(const char *env_value) {
    if (env_value == nullptr) return -1;
    char *end = nullptr;
    long parsed = strtol(env_value, &end, 10);
    if (end == env_value || *end != '\0') return -1;
    if (parsed < 1 || parsed > 65535) return -1;
    return static_cast<int>(parsed);
}

